const input = $input.first().json || {};
const task = String(input.taches || input.task || input.query || '').trim();
const priority = String(input.priorite || 'normale');
const outputType = String(input.output_type || 'liste_prospects');
const countMatch = task.match(/\b(\d{1,2})\b/);
const targetCount = Math.min(Math.max(countMatch ? Number(countMatch[1]) : 10, 1), 20);

function extractCity(text) {
 const patterns = [/\b(?:à|a|in|near)\s+([A-ZÀ-Ÿ][\wÀ-ÿ' -]{2,})/i, /\b(Gatineau|Ottawa|Montréal|Montreal|Québec|Quebec|Laval|Longueuil|Sherbrooke|Trois-Rivières)\b/i];
 for (const pattern of patterns) {
 const match = text.match(pattern);
 if (match) return match[1].replace(/\s+(?:Québec|Quebec|Canada)$/i, '').trim();
 }
 return 'Gatineau';
}

function extractSector(text) {
 const withoutCount = text.replace(/\b(trouver|cherche|chercher|liste|prospects?|entreprises?|compagnies?|businesses?)\b/gi, ' ')
 .replace(/\b\d{1,2}\b/g, ' ')
 .replace(/\b(?:à|a|in|near)\s+[A-ZÀ-Ÿ][\wÀ-ÿ' -]+/i, ' ')
 .replace(/\s+/g, ' ')
 .trim();
 return withoutCount || 'entreprises locales';
}

const city = extractCity(task);
const sector = extractSector(task);
const query = `${sector} ${city} Québec Canada site web téléphone contact adresse`;

return [{
 json: {
 ...input,
 prospect_task: task,
 priority,
 outputType,
 targetCount,
 city,
 sector,
 serpQuery: query,
 generatedAt: new Date().toISOString()
 }
}];

const search = $input.first().json || {};
const request = $('Build Prospect Search').first().json || {};
const targetCount = Number(request.targetCount || 10);

const candidates = [];
const localRaw = search.local_results;
if (Array.isArray(localRaw)) candidates.push(...localRaw.map(x => ({...x, source_type: 'local_results'})));
if (localRaw && Array.isArray(localRaw.places)) candidates.push(...localRaw.places.map(x => ({...x, source_type: 'local_results.places'})));
if (Array.isArray(search.place_results)) candidates.push(...search.place_results.map(x => ({...x, source_type: 'place_results'})));
if (Array.isArray(search.organic_results)) candidates.push(...search.organic_results.map(x => ({...x, source_type: 'organic_results'})));

const seen = new Set();
const prospects = [];
for (const item of candidates) {
 const name = String(item.title || item.name || '').trim();
 if (!name) continue;
 const key = name.toLowerCase().replace(/[^a-z0-9à-ÿ]+/gi, '');
 if (seen.has(key)) continue;
 seen.add(key);
 const website = item.website || item.link || item.displayed_link || item.links?.website || '';
 const phone = item.phone || item.phone_number || item.extensions?.find?.(x => /^\+?\d|\(\d/.test(String(x))) || '';
 const address = item.address || item.snippet || item.rich_snippet?.top?.detected_extensions?.address || '';
 const rating = item.rating || item.reviews_rating || '';
 const reviews = item.reviews || item.reviews_original || '';
 const type = item.type || item.category || request.sector || '';
 const sourceUrl = item.place_id_search || item.link || item.serpapi_link || item.links?.directions || '';
 prospects.push({
 nom: name,
 secteur: type,
 ville_ou_region: request.city || '',
 adresse: String(address || '').replace(/\s+/g, ' ').trim(),
 telephone: String(phone || '').trim(),
 site_web: String(website || '').trim(),
 note_google: rating || null,
 avis: reviews || null,
 source: item.source_type || 'serpapi',
 source_url: sourceUrl,
 pourquoi_bon_prospect: `Entreprise locale dans le secteur ${request.sector || 'cible'}, pertinente pour une approche Cadence orientee reception IA, suivis automatises et reduction des taches repetitives.`,
 douleur_probable: 'Appels manques, demandes de rendez-vous, suivis clients et gestion repetitive des demandes entrantes.',
 score_sur_100: rating ? 78 : 70,
 angle_approche: `Proposer a ${name} une reception IA et des suivis automatises pour capter plus de demandes sans ajouter de charge administrative.`,
 message_brouillon: `Bonjour, je vous contacte parce que Cadence aide les entreprises locales comme ${name} a automatiser la reception, les suivis et certaines taches repetitives. Seriez-vous ouvert a un court echange pour voir ou l'IA pourrait vous faire gagner du temps?`,
 prochaine_action: 'Verifier le site web et preparer un premier contact personnalise.',
 statut_hubspot_propose: 'a enrichir'
 });
 if (prospects.length >= targetCount) break;
}

const status = prospects.length > 0 ? (prospects.length >= targetCount ? 'done' : 'partial') : 'no_results';
const resume = prospects.length > 0
 ? `Recherche terminee pour ${request.prospect_task || request.serpQuery}. ${prospects.length} prospect(s) structure(s) trouve(s) sur ${targetCount} demande(s).`
 : `Aucun prospect exploitable trouve pour ${request.prospect_task || request.serpQuery}.`;

const prospectsPreview = prospects.slice(0, 10).map((p, index) => ({
 rang: index + 1,
 nom: p.nom,
 telephone: p.telephone,
 site_web: p.site_web,
 score_sur_100: p.score_sur_100,
 prochaine_action: p.prochaine_action
}));

const prospectLines = prospectsPreview.map(p => {
 const details = [p.nom];
 if (p.telephone) details.push(p.telephone);
 if (p.site_web) details.push(p.site_web);
 if (p.score_sur_100) details.push(`score ${p.score_sur_100}/100`);
 return `${p.rang}. ${details.join(' | ')}`;
});

const sheetResult = [
 resume,
 '',
 prospectLines.length ? 'Prospects principaux:' : '',
 ...prospectLines,
 prospects.length > prospectsPreview.length ? `+ ${prospects.length - prospectsPreview.length} autre(s) prospect(s) dans la sortie complete n8n.` : '',
 '',
 prospects.length > 0
 ? 'Prochaine action: valider les entreprises retenues et personnaliser les premiers contacts.'
 : 'Prochaine action: preciser la recherche puis relancer.'
].filter(Boolean).join('\n');

return [{
 json: {
 workflow: 'Cadence - Prospect AI',
 status,
 mode: 'deterministic_serpapi_search',
 task: request.prospect_task || '',
 query: request.serpQuery || '',
 targetCount,
 foundCount: prospects.length,
 resume,
 sheet_result: sheetResult,
 prospects_preview: prospectsPreview,
 prospects,
 guardrails: [
 'Aucune creation HubSpot automatique',
 'Donnees issues de SerpAPI/Google quand disponibles',
 'Contacts personnels non inventes',
 'Fiches brouillons pour validation humaine'
 ],
 nextSteps: prospects.length > 0
 ? ['Valider les entreprises retenues', 'Enrichir les fiches prioritaires', 'Creer ou mettre a jour HubSpot seulement sur demande explicite']
 : ['Preciser le secteur ou la ville', 'Relancer avec une requete plus ciblee'],
 rawSearchMetadata: {
 search_metadata: search.search_metadata || null,
 search_parameters: search.search_parameters || null
 },
 completedAt: new Date().toISOString()
 }
}];
